from format_lecon import Lesson,paras,table,steps
l=Lesson('Paralysie du nerf oculomoteur (III)',6)
l.add('La {paralysie du nerf oculomoteur associe des déficits moteurs variables}. Elle peut toucher la paupière, plusieurs mouvements de l’œil et la pupille. Une atteinte acquise impose une recherche urgente de cause.',paras('Le III innerve le releveur de la paupière supérieure, les droits médial, supérieur et inférieur, ainsi que l’oblique inférieur. Son contingent parasympathique participe à la constriction pupillaire et à l’accommodation.', 'Une paralysie complète peut associer ptosis, œil dévié en dehors et vers le bas, et mydriase. Une forme partielle ne reproduit pas nécessairement ce tableau. Le terme isolée signifie sans autre signe neurologique identifié ; il ne signifie pas bénigne.'),(5,16))
l.add('Le {contexte oriente sans exclure une compression vasculaire}. Diabète et facteurs vasculaires rendent une neuropathie microvasculaire possible. Ils ne dispensent pas de l’imagerie initiale.',paras('Aucune fréquence suisse populationnelle récente propre à cette paralysie n’a été retrouvée dans les sources lues. La série britannique discutée par Patel et Burdon comprend 47 patients adressés avec une paralysie isolée ; la forte proportion d’anévrismes dans ce recrutement spécialisé ne doit pas devenir un risque individuel universel.', 'Les causes comprennent neuropathie microvasculaire, anévrisme, traumatisme, inflammation, tumeur et lésion du tronc cérébral. La chronologie, la douleur, la pupille et les signes associés orientent les examens, mais ne constituent pas un filtre permettant de renoncer à l’imagerie.', 'La publication mise en ligne le 15 décembre 2020 recommande une imagerie de toute paralysie isolée du III à sa présentation. Cette stratégie actualise l’ancienne distinction fondée uniquement sur la pupille.'),(5,16))
l.add('La {localisation relie les déficits à la cause recherchée}. Une compression peut toucher les fibres pupillaires. Leur préservation ne garantit pas l’absence d’anévrisme.',table(['Mécanisme','Signe ou examen utile','Conséquence'],[['Atteinte motrice du III.','Ptosis et limitation de l’adduction, de l’élévation ou de l’abaissement.','Décrire le déficit complet ou partiel avant toute compensation.'],['Atteinte parasympathique.','Comparer taille et réactivité des pupilles avant instillation.','Une mydriase renforce l’alarme compressive.'],['Compression vasculaire du trajet intracrânien.','Angiographie par scanner ou résonance magnétique adaptée.','Identifier rapidement un anévrisme potentiellement menaçant.'],['Atteinte du tronc cérébral ou de plusieurs structures.','Examen neurologique et recherche de signes voisins.','Étendre l’exploration au-delà d’une neuropathie isolée.']])+paras('La règle historique opposant atteinte externe microvasculaire à atteinte interne compressive comporte des exceptions. Une atteinte partielle avec pupille normale est particulièrement impropre à une conclusion rassurante. La décision repose sur l’exploration, pas sur cette simplification.'),(5,16))
l.add('La {priorité est d’exclure anévrisme et urgence neurologique}. Une céphalée brutale, une altération de conscience ou un déficit focal impose les urgences. Une paralysie isolée nouvelle justifie également une évaluation et une imagerie rapides.',paras('Une paralysie douloureuse avec mydriase fait craindre notamment un anévrisme de l’artère communicante postérieure. Ne pas organiser d’abord une simple consultation de correction du strabisme. En Suisse, un tableau aigu sévère relève du 144 et du parcours neurovasculaire.', 'Une pupille réactive ou l’absence de douleur ne permet pas de supprimer cette recherche. Une céphalée en coup de tonnerre conduit au parcours d’hémorragie sous-arachnoïdienne, avec ses examens propres, au-delà du seul bilan oculomoteur.', 'Une baisse visuelle, une exophtalmie, plusieurs nerfs atteints ou des signes généraux font envisager une atteinte orbitaire, du sinus caverneux ou systémique. Chez un patient de plus de 50 ans, rechercher aussi les signes d’artérite à cellules géantes si le contexte les évoque.'),(2,5,16))
l.add('L’{anamnèse date précisément ptosis, diplopie et douleur}. Distinguer début brutal, progression et récidive. Demander les symptômes neurologiques et l’exposition aux collyres.',paras('Rechercher céphalée inhabituelle, douleur orbitaire, traumatisme, baisse visuelle, nausées et trouble de conscience. La chronologie doit préciser si le déficit s’aggrave, même lorsque le patient ne voit pas double parce que sa paupière ferme l’œil.', 'Recueillir facteurs vasculaires, antécédents tumoraux ou inflammatoires, médicaments et instillations mydriatiques. Un collyre peut modifier la pupille, mais ne doit pas expliquer sans examen un déficit moteur associé.', 'Interroger sur fluctuation et fatigabilité pour la myasthénie, ainsi que sur signes thyroïdiens ou orbitaires. Le terrain diabétique est une donnée de contexte, non une preuve étiologique.'),(5,13,16))
l.add('L’{examen documente la pupille avant toute dilatation}. Mesurer l’acuité et examiner les paupières, puis la motilité. Compléter par un examen neurologique et orbitaire.',paras('Comparer les pupilles dans des conditions lumineuses contrôlées et tester les réponses à la lumière. Noter anisocorie, réactivité et contexte médicamenteux. Une photographie clinique datée peut documenter une évolution, selon les règles de consentement du service.', 'Examiner adduction, élévation et abaissement de chaque œil, puis alignement et diplopie dans les différents regards. Le ptosis complet peut masquer la diplopie ; relever doucement la paupière pour examiner sans conclure à une absence de gêne binoculaire.', 'Rechercher les autres nerfs crâniens, déficit moteur ou sensitif, ataxie et signes méningés. Une réduction de vision ou une exophtalmie fait rechercher une atteinte orbitaire associée. L’examen répété ne remplace pas l’imagerie initiale indiquée.'),(5,16))
l.add('Les {formes complètes, partielles et associées orientent la localisation}. La pupille peut être atteinte ou respectée dans chaque bilan initial. Une évolution impose de réexaminer la classification.',paras('7.1. La forme complète externe associe plusieurs limitations et un ptosis ; l’atteinte interne désigne la participation pupillaire. Ces descriptions sont anatomiques et ne fixent pas à elles seules la cause.', '7.2. La forme partielle peut ne toucher qu’une partie des fonctions. La qualifier de bénigne parce que la pupille paraît normale est un piège.', '7.3. La forme avec signes neurologiques, orbitaires ou atteinte d’autres nerfs exige une localisation plus large. Les recommandations britanniques pour les paralysies isolées ne sont pas une raison de réduire ce bilan.'),(5,16))
l.add('Le {diagnostic positif repose sur un déficit moteur compatible}. Il faut distinguer neuropathie, trouble de transmission et restriction. L’étiologie reste à établir même si la sémiologie est typique.',paras('La combinaison des mouvements atteints et du ptosis oriente vers le III. Une myasthénie peut imiter plusieurs profils oculomoteurs et épargne habituellement les pupilles ; une fatigabilité et une variabilité conduisent à des tests spécifiques.', 'Une orbitopathie restrictive, une lésion orbitaire ou une anomalie ancienne peuvent expliquer certaines limitations. Des données discordantes doivent conduire à réviser la localisation. Il n’existe pas de critère clinique unique qui autorise à exclure un anévrisme dans une paralysie isolée nouvelle.'),(5,11,13,16))
l.add('L’{imagerie initiale doit explorer les causes vasculaires pertinentes}. Le choix entre angioscanner et angio-IRM dépend du contexte et de l’équipe. Une interprétation experte est essentielle.',paras('9.a. Patel et Burdon recommandent l’imagerie à la présentation de toute paralysie isolée du III, avec analyse par un neuroradiologue expérimenté. Une simple imagerie cérébrale non vasculaire ne répond pas nécessairement à la question anévrismale.', '9.b. Le protocole recherche un anévrisme et, selon les signes, une autre lésion sur le trajet du nerf. L’angioscanner et l’angio-IRM sont des approches non invasives ; leur pertinence dépend de la qualité technique, des contre-indications et de l’expertise.', '9.c. Si une modalité est indisponible ou contre-indiquée, organiser une alternative appropriée avec l’équipe urgente. Ne pas convertir une contrainte logistique en autorisation d’attendre sans stratégie.', '9.d. Si le résultat est négatif mais la suspicion forte, l’examen incomplet ou l’évolution discordante, demander une relecture spécialisée et discuter les explorations complémentaires. L’angiographie invasive est une décision experte, pas un examen automatique de tous les patients.')+table(['Résultat ou situation','Conséquence'],[['Un anévrisme est identifié.','Avis neurovasculaire et neurochirurgical urgent.'],['Une autre lésion explique le déficit.','Traitement étiologique dans la filière concernée.'],['L’imagerie est rassurante et le profil paraît microvasculaire.','Suivi clinique organisé et prise en charge du terrain, avec consignes de retour.'],['Le déficit progresse malgré un premier bilan négatif.','Réévaluation rapide et vérification de la qualité du bilan initial.']]),(5,16))
l.add('L’{algorithme ne dépend pas d’une pupille rassurante}. Identifier l’urgence, localiser et imager. Traiter ensuite la cause et le handicap visuel.',steps('Adresser immédiatement les signes d’urgence neurologique ou de suspicion anévrismale.', 'Documenter pupilles, motilité, ptosis, vision et examen neurologique.', 'Organiser l’imagerie initiale vasculaire et anatomique adaptée pour une nouvelle paralysie du III.', 'Faire interpréter les résultats par une équipe expérimentée et réévaluer toute discordance.', 'Après sécurisation, soulager la diplopie et organiser suivi étiologique et fonctionnel.'),(5,16))
l.add('La {prise en charge est d’abord étiologique}. L’occlusion ou les prismes ne traitent pas un anévrisme. Une correction durable attend l’évaluation de l’évolution.',paras('11.A. La priorité est de prévenir le dommage neurologique, puis de préserver une vision utile et de réduire la diplopie. Le pronostic dépend de la cause et de l’étendue du déficit.', '11.B. Une occlusion peut soulager une diplopie pendant le bilan ou la récupération. Un prisme est parfois utile si la déviation et sa variabilité le permettent ; une paralysie complexe ne devient pas toujours compensable dans tous les regards.', '11.B. Une déviation résiduelle stable peut justifier une chirurgie spécialisée. La correction du ptosis et celle de l’alignement doivent être coordonnées, car une paupière relevée peut révéler une diplopie auparavant masquée.', '11.C. L’anévrisme, l’hémorragie ou une autre cause urgente relèvent d’un traitement spécialisé immédiat. Aucun traitement médicamenteux empirique du strabisme n’est proposé ici comme substitut à cette filière.', '11.D. Fixer un rendez-vous de contrôle et des consignes explicites : nouvelle céphalée, pupille changeante, baisse visuelle, aggravation ou signe neurologique justifient un retour rapide. Adapter les déplacements et la conduite à la diplopie et à l’avis médical. Chez l’enfant, intégrer le risque d’amblyopie au suivi spécialisé.'),(3,5,16))
l.add('La {prévention porte sur le terrain et la détection des changements}. Prendre en charge les facteurs vasculaires identifiés. Expliquer les signes qui imposent une nouvelle consultation.',paras('La prévention primaire comprend les mesures cardiovasculaires adaptées au patient et la protection contre les traumatismes. Elle ne permet pas d’exclure une cause compressive à l’apparition du déficit.', 'La prévention secondaire repose sur l’évaluation rapide d’un ptosis ou d’une diplopie nouvellement apparus. La prévention tertiaire associe rééducation fonctionnelle adaptée, aides optiques et correction spécialisée si nécessaire, sans promesse de récupération complète.'),(5,16))
l.add('Les {points clés sont l’urgence et la qualité de l’imagerie}. Une pupille normale ne suffit pas à rassurer. Un ptosis peut cacher la diplopie.',paras('Toute paralysie isolée nouvelle du III mérite une exploration initiale selon la stratégie britannique lue. La présence de diabète ne prouve pas une origine microvasculaire. Une lecture neuroradiologique expérimentée et la concordance avec l’évolution sont essentielles. Les mesures symptomatiques viennent après la sécurisation du parcours.'),(5,16))
l.quiz([('Quel nerf innerve le releveur de la paupière supérieure ?','Le III.'),('Une paralysie partielle doit-elle être explorée ?','Oui.'),('Une pupille normale exclut-elle un anévrisme ?','Non.'),('Le diabète établit-il la cause du déficit ?','Non.'),('Un ptosis complet peut-il masquer la diplopie ?','Oui.'),('Quand documenter la pupille ?','Avant toute instillation susceptible de la modifier.'),('Une céphalée en coup de tonnerre attend-elle le bilan ambulatoire ?','Non.'),('Un scanner non vasculaire répond-il toujours à la question anévrismale ?','Non.'),('Qui doit interpréter une imagerie difficile ou discordante ?','Une équipe expérimentée, notamment en neuroradiologie.'),('La série de 47 patients fournit-elle une prévalence suisse ?','Non.'),('Une imagerie négative clôt-elle le bilan si le déficit progresse ?','Non ; il faut réévaluer.'),('Un prisme traite-t-il la cause compressive ?','Non.'),('La chirurgie du ptosis peut-elle révéler une diplopie ?','Oui.'),('Les autres signes neurologiques réduisent-ils le besoin d’exploration ?','Non ; ils élargissent et peuvent rendre plus urgent le bilan.')],(5,16))
l.write()
